-- SOURCE CANDIDATE: confirmed official roster invalidity fences current research.
-- Three finite body changes only; no functions, permissions, roles, policies or quota changes.
BEGIN ISOLATION LEVEL READ COMMITTED;
SET LOCAL statement_timeout='30s';SET LOCAL lock_timeout='2s';
SELECT pg_advisory_xact_lock(64221022);
DO $roster_current$
DECLARE provider_target oid:=to_regprocedure('public.vnext_provider_command_v1(text,text,jsonb)');core_target oid:=to_regprocedure('public.vnext_command_v1(text,text,jsonb)');target oid:=to_regprocedure('public.vnext_input_sources_current_v1(jsonb,text)');original text;changed text;definition text;metadata jsonb;before_namespace jsonb;after_namespace jsonb;helper oid:=to_regprocedure('public.vnext_trading_invalid_current_v1(text,text)');
 catalog_sql constant text:=$catalog$
 SELECT jsonb_build_object(
  'namespace',(SELECT to_jsonb(n) FROM pg_namespace n WHERE n.oid='public'::regnamespace),
  'routines',(SELECT coalesce(jsonb_agg(CASE WHEN p.oid=ANY($1) THEN to_jsonb(p)-'prosrc' ELSE to_jsonb(p) END ORDER BY p.oid),'[]'::jsonb) FROM pg_proc p WHERE p.pronamespace='public'::regnamespace),
  'relations',(SELECT coalesce(jsonb_agg(to_jsonb(c) ORDER BY c.oid),'[]'::jsonb) FROM pg_class c WHERE c.relnamespace='public'::regnamespace),
  'columns',(SELECT coalesce(jsonb_agg(to_jsonb(a) ORDER BY a.attrelid,a.attnum),'[]'::jsonb) FROM pg_attribute a WHERE a.attrelid IN(SELECT oid FROM pg_class WHERE relnamespace='public'::regnamespace)),
  'types',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY t.oid),'[]'::jsonb) FROM pg_type t WHERE t.typnamespace='public'::regnamespace),
  'constraints',(SELECT coalesce(jsonb_agg(to_jsonb(c) ORDER BY c.oid),'[]'::jsonb) FROM pg_constraint c WHERE c.connamespace='public'::regnamespace),
  'defaults',(SELECT coalesce(jsonb_agg(to_jsonb(d) ORDER BY d.oid),'[]'::jsonb) FROM pg_attrdef d WHERE d.adrelid IN(SELECT oid FROM pg_class WHERE relnamespace='public'::regnamespace)),
  'indexes',(SELECT coalesce(jsonb_agg(to_jsonb(i) ORDER BY i.indexrelid),'[]'::jsonb) FROM pg_index i WHERE i.indrelid IN(SELECT oid FROM pg_class WHERE relnamespace='public'::regnamespace)),
  'policies',(SELECT coalesce(jsonb_agg(to_jsonb(p) ORDER BY p.oid),'[]'::jsonb) FROM pg_policy p WHERE p.polrelid IN(SELECT oid FROM pg_class WHERE relnamespace='public'::regnamespace)),
  'triggers',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY t.oid),'[]'::jsonb) FROM pg_trigger t WHERE t.tgrelid IN(SELECT oid FROM pg_class WHERE relnamespace='public'::regnamespace)),
  'rules',(SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY r.oid),'[]'::jsonb) FROM pg_rewrite r WHERE r.ev_class IN(SELECT oid FROM pg_class WHERE relnamespace='public'::regnamespace)),
  'operators',(SELECT coalesce(jsonb_agg(to_jsonb(o) ORDER BY o.oid),'[]'::jsonb) FROM pg_operator o WHERE o.oprnamespace='public'::regnamespace),
  'collations',(SELECT coalesce(jsonb_agg(to_jsonb(c) ORDER BY c.oid),'[]'::jsonb) FROM pg_collation c WHERE c.collnamespace='public'::regnamespace),
  'defaultAcls',(SELECT coalesce(jsonb_agg(to_jsonb(a) ORDER BY a.oid),'[]'::jsonb) FROM pg_default_acl a WHERE a.defaclnamespace IN(0,'public'::regnamespace)),
  'roleSettings',(SELECT coalesce(jsonb_agg(to_jsonb(s) ORDER BY s.setdatabase,s.setrole),'[]'::jsonb) FROM pg_db_role_setting s),'roles',(SELECT jsonb_agg(to_jsonb(r) ORDER BY r.rolname) FROM pg_roles r),
  'memberships',(SELECT coalesce(jsonb_agg(to_jsonb(m) ORDER BY m.roleid,m.member),'[]'::jsonb) FROM pg_auth_members m))
 $catalog$;
BEGIN
 IF current_setting('transaction_isolation') IS DISTINCT FROM 'read committed' OR target IS NULL OR helper IS NULL OR core_target IS NULL OR provider_target IS NULL THEN RAISE EXCEPTION 'vnext_roster_current_prerequisites_missing';END IF;
 IF NOT EXISTS(SELECT FROM pg_roles WHERE rolname='stockinsider_vnext_owner' AND NOT rolcanlogin AND NOT rolsuper AND NOT rolcreatedb AND NOT rolcreaterole AND NOT rolreplication AND NOT rolbypassrls AND rolconfig IS NULL) OR EXISTS(SELECT FROM pg_auth_members WHERE member='stockinsider_vnext_owner'::regrole OR roleid='stockinsider_vnext_owner'::regrole) OR EXISTS(SELECT FROM pg_db_role_setting WHERE setrole='stockinsider_vnext_owner'::regrole AND setconfig IS NOT NULL) THEN RAISE EXCEPTION 'vnext_roster_current_owner_profile_changed';END IF;
 IF NOT EXISTS(SELECT FROM pg_proc p WHERE p.oid=to_regprocedure('public.vnext_command_v1(text,text,jsonb)') AND pg_get_userbyid(p.proowner)='stockinsider_vnext_owner' AND p.prosecdef AND encode(sha256(convert_to(p.prosrc,'UTF8')),'hex')='c2df728571a9b9914f87acc6cead6d444af2ea0c638e058db50da4bc74ef146c') THEN RAISE EXCEPTION 'vnext_roster_current_trading_core_changed';END IF;
 IF NOT EXISTS(SELECT FROM pg_proc p JOIN pg_language l ON l.oid=p.prolang WHERE p.oid=helper AND pg_get_userbyid(p.proowner)='stockinsider_vnext_owner' AND p.prosecdef AND p.prokind='f' AND NOT p.proretset AND l.lanname='plpgsql' AND p.prorettype='jsonb'::regtype AND p.pronargs=2 AND p.proargtypes='25 25'::oidvector AND p.proargnames=ARRAY['p_symbol','p_input_hash'] AND p.proallargtypes IS NULL AND p.proargmodes IS NULL AND p.provariadic=0 AND p.pronargdefaults=0 AND p.proargdefaults IS NULL AND p.provolatile='s' AND p.proparallel='u' AND NOT p.proisstrict AND NOT p.proleakproof AND p.proconfig=ARRAY['search_path=pg_catalog, public','statement_timeout=30s','lock_timeout=2s'] AND p.procost=100 AND p.prorows=0 AND p.probin IS NULL AND p.prosqlbody IS NULL AND encode(sha256(convert_to(p.prosrc,'UTF8')),'hex')='dac9ffaf049c8cabfe3f0fa166293447484f69c4daf06b4c6154f3179f396f58') THEN RAISE EXCEPTION 'vnext_roster_current_private_checker_changed';END IF;
 IF (SELECT count(*) FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) acl WHERE p.oid=helper)<>1 OR EXISTS(SELECT FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) acl WHERE p.oid=helper AND (acl.grantee<>p.proowner OR acl.grantor<>p.proowner OR acl.privilege_type<>'EXECUTE' OR acl.is_grantable)) THEN RAISE EXCEPTION 'vnext_roster_current_private_acl_changed';END IF;
 SELECT prosrc,pg_get_functiondef(oid),to_jsonb(p)-'prosrc' INTO original,definition,metadata FROM pg_proc p WHERE oid=target;
 IF encode(sha256(convert_to(original,'UTF8')),'hex')<>'83c21c7f7247045c0fe8f66d8d6ae5dbc88c72286ef38274ca8d8a11fe9ca352' OR NOT EXISTS(SELECT FROM pg_proc p JOIN pg_language l ON l.oid=p.prolang WHERE p.oid=target AND pg_get_userbyid(p.proowner)='stockinsider_vnext_owner' AND p.prosecdef AND p.prokind='f' AND NOT p.proretset AND l.lanname='sql' AND p.prorettype='boolean'::regtype AND p.pronargs=2 AND p.proargtypes='3802 25'::oidvector AND p.proargnames=ARRAY['input','p_symbol'] AND p.proallargtypes IS NULL AND p.proargmodes IS NULL AND p.provariadic=0 AND p.pronargdefaults=0 AND p.proargdefaults IS NULL AND p.provolatile='s' AND p.proparallel='u' AND NOT p.proisstrict AND NOT p.proleakproof AND p.proconfig=ARRAY['search_path=pg_catalog, public'] AND p.procost=100 AND p.prorows=0 AND p.probin IS NULL AND p.prosqlbody IS NULL) THEN RAISE EXCEPTION 'vnext_roster_current_predecessor_changed';END IF;
 IF (SELECT count(*) FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) acl WHERE p.oid=target)<>1 OR EXISTS(SELECT FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) acl WHERE p.oid=target AND (acl.grantee<>p.proowner OR acl.grantor<>p.proowner OR acl.privilege_type<>'EXECUTE' OR acl.is_grantable)) THEN RAISE EXCEPTION 'vnext_roster_current_source_acl_changed';END IF;
 changed:=original||$fence$ AND NOT EXISTS(SELECT FROM public.vnext_members_v1 current_member WHERE current_member.symbol=p_symbol AND public.vnext_trading_invalid_current_v1(current_member.symbol,current_member.input_hash) ? 'proofHash')
$fence$;
 IF left(changed,length(original)) IS DISTINCT FROM original OR right(changed,length($fence$ AND NOT EXISTS(SELECT FROM public.vnext_members_v1 current_member WHERE current_member.symbol=p_symbol AND public.vnext_trading_invalid_current_v1(current_member.symbol,current_member.input_hash) ? 'proofHash')
$fence$)) IS DISTINCT FROM $fence$ AND NOT EXISTS(SELECT FROM public.vnext_members_v1 current_member WHERE current_member.symbol=p_symbol AND public.vnext_trading_invalid_current_v1(current_member.symbol,current_member.input_hash) ? 'proofHash')
$fence$ OR left(changed,length(changed)-length($fence$ AND NOT EXISTS(SELECT FROM public.vnext_members_v1 current_member WHERE current_member.symbol=p_symbol AND public.vnext_trading_invalid_current_v1(current_member.symbol,current_member.input_hash) ? 'proofHash')
$fence$)) IS DISTINCT FROM original OR encode(sha256(convert_to(changed,'UTF8')),'hex')<>'2e6a155ce7148f2ab550c414297bae42519339e9a4b7bad2ab658ce9a4ab398a' THEN RAISE EXCEPTION 'vnext_roster_current_inverse_failed';END IF;
 IF NOT EXISTS(SELECT FROM pg_proc p JOIN pg_language l ON l.oid=p.prolang WHERE p.oid=core_target AND pg_get_userbyid(p.proowner)='stockinsider_vnext_owner' AND p.prosecdef AND p.prokind='f' AND NOT p.proretset AND l.lanname='plpgsql' AND p.prorettype='jsonb'::regtype AND p.pronargs=3 AND p.proargtypes='25 25 3802'::oidvector AND p.proargnames=ARRAY['p_principal','p_command','p_request'] AND p.proallargtypes IS NULL AND p.proargmodes IS NULL AND p.provariadic=0 AND p.pronargdefaults=0 AND p.proargdefaults IS NULL AND p.provolatile='v' AND p.proparallel='u' AND NOT p.proisstrict AND NOT p.proleakproof AND p.proconfig=ARRAY['search_path=pg_catalog, public'] AND p.procost=100 AND p.prorows=0 AND p.probin IS NULL AND p.prosqlbody IS NULL) THEN RAISE EXCEPTION 'vnext_roster_current_core_metadata_changed';END IF;
 IF (SELECT count(*) FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) acl WHERE p.oid=core_target)<>2 OR EXISTS(SELECT FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) acl WHERE p.oid=core_target AND (acl.grantee NOT IN(p.proowner,'service_role'::regrole::oid) OR acl.grantor<>p.proowner OR acl.privilege_type<>'EXECUTE' OR acl.is_grantable)) OR NOT has_function_privilege('service_role',core_target,'EXECUTE') THEN RAISE EXCEPTION 'vnext_roster_current_core_acl_changed';END IF;
 IF NOT EXISTS(SELECT FROM pg_proc p WHERE p.oid=provider_target AND encode(sha256(convert_to(p.prosrc,'UTF8')),'hex')='3ca260d5bf8fc594642564b07b7085e34e01c8a4e4b8bd179022650090cf6ea2') THEN RAISE EXCEPTION 'vnext_roster_current_provider_predecessor_changed';END IF;
 IF NOT EXISTS(SELECT FROM pg_proc p JOIN pg_language l ON l.oid=p.prolang WHERE p.oid=provider_target AND pg_get_userbyid(p.proowner)='stockinsider_vnext_owner' AND p.prosecdef AND p.prokind='f' AND NOT p.proretset AND l.lanname='plpgsql' AND p.prorettype='jsonb'::regtype AND p.pronargs=3 AND p.proargtypes='25 25 3802'::oidvector AND p.proargnames=ARRAY['p_principal','p_command','p_request'] AND p.proallargtypes IS NULL AND p.proargmodes IS NULL AND p.provariadic=0 AND p.pronargdefaults=0 AND p.proargdefaults IS NULL AND p.provolatile='v' AND p.proparallel='u' AND NOT p.proisstrict AND NOT p.proleakproof AND p.proconfig=ARRAY['search_path=pg_catalog, public','statement_timeout=30s','lock_timeout=2s'] AND p.procost=100 AND p.prorows=0 AND p.probin IS NULL AND p.prosqlbody IS NULL) THEN RAISE EXCEPTION 'vnext_roster_current_provider_metadata_changed';END IF;
 IF (SELECT count(*) FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) acl WHERE p.oid=provider_target)<>2 OR EXISTS(SELECT FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) acl WHERE p.oid=provider_target AND (acl.grantee NOT IN(p.proowner,'service_role'::regrole::oid) OR acl.grantor<>p.proowner OR acl.privilege_type<>'EXECUTE' OR acl.is_grantable)) OR NOT has_function_privilege('service_role',provider_target,'EXECUTE') THEN RAISE EXCEPTION 'vnext_roster_current_provider_acl_changed';END IF;
 EXECUTE catalog_sql INTO before_namespace USING ARRAY[target,core_target,provider_target];
 EXECUTE replace(definition,original,changed);
 IF to_regprocedure('public.vnext_input_sources_current_v1(jsonb,text)')::oid IS DISTINCT FROM target OR (SELECT to_jsonb(p)-'prosrc' FROM pg_proc p WHERE oid=target) IS DISTINCT FROM metadata OR (SELECT prosrc FROM pg_proc WHERE oid=target) IS DISTINCT FROM changed THEN RAISE EXCEPTION 'vnext_roster_current_metadata_changed';END IF;
 SELECT prosrc,pg_get_functiondef(oid),to_jsonb(p)-'prosrc' INTO original,definition,metadata FROM pg_proc p WHERE oid=core_target;
 IF encode(sha256(convert_to(original,'UTF8')),'hex')<>'c2df728571a9b9914f87acc6cead6d444af2ea0c638e058db50da4bc74ef146c' OR (length(original)-length(replace(original,$claim_old$  IF m.state='exited' OR m.contraindication OR m.input_hash<>j.input_hash THEN RAISE EXCEPTION 'vnext_admission_invalid'; END IF;
  IF j.state<>'queued' THEN RETURN jsonb_build_object('replay',true,'state',j.state,'execute',false); END IF;$claim_old$,'')))<>length($claim_old$  IF m.state='exited' OR m.contraindication OR m.input_hash<>j.input_hash THEN RAISE EXCEPTION 'vnext_admission_invalid'; END IF;
  IF j.state<>'queued' THEN RETURN jsonb_build_object('replay',true,'state',j.state,'execute',false); END IF;$claim_old$) THEN RAISE EXCEPTION 'vnext_roster_current_claim_predecessor_changed';END IF;
 changed:=replace(original,$claim_old$  IF m.state='exited' OR m.contraindication OR m.input_hash<>j.input_hash THEN RAISE EXCEPTION 'vnext_admission_invalid'; END IF;
  IF j.state<>'queued' THEN RETURN jsonb_build_object('replay',true,'state',j.state,'execute',false); END IF;$claim_old$,$claim_new$  IF m.state='exited' OR m.contraindication OR m.input_hash<>j.input_hash THEN RAISE EXCEPTION 'vnext_admission_invalid'; END IF;
  IF public.vnext_trading_invalid_current_v1(j.symbol,j.input_hash) ? 'proofHash' THEN RAISE EXCEPTION 'vnext_claim_confirmed_trading_invalid';END IF;
  IF j.state<>'queued' THEN RETURN jsonb_build_object('replay',true,'state',j.state,'execute',false); END IF;$claim_new$);
 IF replace(changed,$claim_new$  IF m.state='exited' OR m.contraindication OR m.input_hash<>j.input_hash THEN RAISE EXCEPTION 'vnext_admission_invalid'; END IF;
  IF public.vnext_trading_invalid_current_v1(j.symbol,j.input_hash) ? 'proofHash' THEN RAISE EXCEPTION 'vnext_claim_confirmed_trading_invalid';END IF;
  IF j.state<>'queued' THEN RETURN jsonb_build_object('replay',true,'state',j.state,'execute',false); END IF;$claim_new$,$claim_old$  IF m.state='exited' OR m.contraindication OR m.input_hash<>j.input_hash THEN RAISE EXCEPTION 'vnext_admission_invalid'; END IF;
  IF j.state<>'queued' THEN RETURN jsonb_build_object('replay',true,'state',j.state,'execute',false); END IF;$claim_old$) IS DISTINCT FROM original OR encode(sha256(convert_to(changed,'UTF8')),'hex')<>'0a5ba7953b1925b26a9ced99764786bb3e7d047bb33264d563447ab5e6353472' THEN RAISE EXCEPTION 'vnext_roster_current_claim_inverse_failed';END IF;
 EXECUTE replace(definition,original,changed);
 IF to_regprocedure('public.vnext_command_v1(text,text,jsonb)')::oid IS DISTINCT FROM core_target OR (SELECT to_jsonb(p)-'prosrc' FROM pg_proc p WHERE oid=core_target) IS DISTINCT FROM metadata OR (SELECT prosrc FROM pg_proc WHERE oid=core_target) IS DISTINCT FROM changed THEN RAISE EXCEPTION 'vnext_roster_current_claim_metadata_changed';END IF;
 SELECT prosrc,pg_get_functiondef(oid),to_jsonb(p)-'prosrc' INTO original,definition,metadata FROM pg_proc p WHERE oid=provider_target;
 IF encode(sha256(convert_to(original,'UTF8')),'hex')<>'3ca260d5bf8fc594642564b07b7085e34e01c8a4e4b8bd179022650090cf6ea2' OR (length(original)-length(replace(original,$reserve_old$ SELECT * INTO invocation FROM public.vnext_provider_invocations_v1 WHERE job_id=j.job_id AND task=role_task;$reserve_old$,'')))<>length($reserve_old$ SELECT * INTO invocation FROM public.vnext_provider_invocations_v1 WHERE job_id=j.job_id AND task=role_task;$reserve_old$) THEN RAISE EXCEPTION 'vnext_roster_current_reserve_predecessor_changed';END IF;
 changed:=replace(original,$reserve_old$ SELECT * INTO invocation FROM public.vnext_provider_invocations_v1 WHERE job_id=j.job_id AND task=role_task;$reserve_old$,$reserve_new$ IF p_command='reserve' AND public.vnext_trading_invalid_current_v1(j.symbol,j.input_hash) ? 'proofHash' THEN RAISE EXCEPTION 'vnext_reserve_confirmed_trading_invalid';END IF;
 SELECT * INTO invocation FROM public.vnext_provider_invocations_v1 WHERE job_id=j.job_id AND task=role_task;$reserve_new$);
 IF replace(changed,$reserve_new$ IF p_command='reserve' AND public.vnext_trading_invalid_current_v1(j.symbol,j.input_hash) ? 'proofHash' THEN RAISE EXCEPTION 'vnext_reserve_confirmed_trading_invalid';END IF;
 SELECT * INTO invocation FROM public.vnext_provider_invocations_v1 WHERE job_id=j.job_id AND task=role_task;$reserve_new$,$reserve_old$ SELECT * INTO invocation FROM public.vnext_provider_invocations_v1 WHERE job_id=j.job_id AND task=role_task;$reserve_old$) IS DISTINCT FROM original OR encode(sha256(convert_to(changed,'UTF8')),'hex')<>'14ffe7baa787f6808f2cb1e3250344766a51698ef722268361ef5512621cbcba' THEN RAISE EXCEPTION 'vnext_roster_current_reserve_inverse_failed';END IF;
 EXECUTE replace(definition,original,changed);
 IF to_regprocedure('public.vnext_provider_command_v1(text,text,jsonb)')::oid IS DISTINCT FROM provider_target OR (SELECT to_jsonb(p)-'prosrc' FROM pg_proc p WHERE oid=provider_target) IS DISTINCT FROM metadata OR (SELECT prosrc FROM pg_proc WHERE oid=provider_target) IS DISTINCT FROM changed THEN RAISE EXCEPTION 'vnext_roster_current_reserve_metadata_changed';END IF;
 EXECUTE catalog_sql INTO after_namespace USING ARRAY[target,core_target,provider_target];
 IF before_namespace IS DISTINCT FROM after_namespace THEN RAISE EXCEPTION 'vnext_roster_current_namespace_changed';END IF;
END $roster_current$;
COMMIT;
